import{_ as t,o,c as r,ag as s}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"The PR Round","description":"","frontmatter":{"source":"project/pr-round.md"},"headers":[],"relativePath":"project/pr-round.md","filePath":"project/pr-round.md"}'),n={name:"project/pr-round.md"};function a(i,e,d,h,l,u){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="the-pr-round" tabindex="-1">The PR Round <a class="header-anchor" href="#the-pr-round" aria-label="Permalink to &quot;The PR Round&quot;">​</a></h1><blockquote><p>For two weeks the class reviews itself at scale: every student opens one real pull request on another team&#39;s fork, and every team reviews and decides on the pull requests that land on its own. You practice both sides of review, on code you didn&#39;t write, on a fixed clock.</p></blockquote><p>The design is UT Austin&#39;s CS 378 PR round, in which &quot;every student or pair opens one real pull request against a classmate&#39;s… repository and reviews the pull request that lands on their own&quot;, on &quot;a fixed one-week clock&quot; (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>).</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>When</strong></td><td>Weeks 9–10. Opens at the week 9 Seminar; closes before the week 11 Seminar</td></tr><tr><td><strong>Who</strong></td><td>Everyone, individually, as an author; everyone, as a member of a receiving team, as a reviewer</td></tr><tr><td><strong>Graded as</strong></td><td>20 points, individual: 10 as author, 10 as reviewer (<a href="./../assessment/rubrics.html#the-pr-round">rubric</a>), counted in Labs and assignments and never dropped</td></tr><tr><td><strong>Clock</strong></td><td>Fixed. Grace tokens don&#39;t apply</td></tr><tr><td><strong>AI use</strong></td><td>🟢 AI on for the code; 🔴 AI off for your PR description and every review comment you sign</td></tr></tbody></table><h2 id="before-the-round" tabindex="-1">Before the round <a class="header-anchor" href="#before-the-round" aria-label="Permalink to &quot;Before the round&quot;">​</a></h2><p>Due with M1, before the week 9 Seminar. Your team prepares its fork to receive PRs:</p><ul><li>☐ <strong>Issues labeled <code>eswa-pr-round</code>:</strong> at least as many as your team has members, plus one, because your fork will receive about one PR per member. Each is small enough for a stranger to finish in about 4 hours, and has a reproduction or a user story, a &quot;done when&quot;, and a pointer to the files involved. Good candidates: a missing test, an edge case your M0 spec lists as out of scope, a small refactor, a documentation fix with a test.</li><li>☐ <strong>CI green on <code>main</code></strong>, and <code>main</code> protected (PRs with one approval).</li><li>☐ <strong>No secrets in the fork:</strong> no Actions secrets, and no other secrets configured in its settings. During the round, authors from other teams get push access to branches, and a PR from a branch in the same repository runs its own version of your workflows with the repository&#39;s secrets (<a href="./../weeks/09-review-at-scale/lab.html#ci-gates-on-your-team-fork">why</a>).</li><li>☐ <strong>A short &quot;Contributing to our fork&quot; section</strong> in the README or <code>AGENTS.md</code>: how to build, how to run the tests, your conventions, and that PRs must follow <a href="./contribution-rules.html">the contribution rules</a>.</li><li>☐ <strong>A reviewer rota:</strong> who on your team reviews which incoming PR, so every member reviews at least one.</li></ul><p>A team fork that isn&#39;t ready by the start of the round (it doesn&#39;t build from its README, or CI is red on <code>main</code>) is left out of the ring as a receiver. Its members still open PRs elsewhere, but review a seeded <code>roomly</code> PR instead of a real one, for at most 5 of the 10 reviewer points. UT Austin applies the same rule: repositories that fail staff checks are left out of the ring.</p><h2 id="the-ring" tabindex="-1">The ring <a class="header-anchor" href="#the-ring" aria-label="Permalink to &quot;The ring&quot;">​</a></h2><p>At the week 9 Seminar the instructor posts the <strong>ring</strong> on Canvas: each student is assigned a <strong>target fork</strong> that isn&#39;t their own team&#39;s, with each team&#39;s members spread across different targets, so every fork receives about as many PRs as its team has members. In your target fork, claim an <code>eswa-pr-round</code> issue nobody has taken by commenting &quot;I&#39;m taking this&quot; on it; first come, first served.</p><p>For the round, staff give each author permission to push branches to their target fork (<code>main</code> stays protected), so you can open your PR from a branch there. Name it <code>pr-round/[github-username]-[issue-number]</code>. If you prefer, open it from your own fork instead.</p><h2 id="week-9-open-your-pr" tabindex="-1">Week 9: open your PR <a class="header-anchor" href="#week-9-open-your-pr" aria-label="Permalink to &quot;Week 9: open your PR&quot;">​</a></h2><p><strong>Due before the week 10 Seminar (default 11:59 pm the night before).</strong></p><ol><li><strong>Read the target fork&#39;s conventions</strong> and its <code>AGENTS.md</code>, and build it in a Codespace.</li><li><strong>Specify · Delegate · Verify</strong> in your own lab repository&#39;s <code>AI_LOG.md</code>, as for any task.</li><li><strong>Make the change</strong> in the Safe Loop. Your agent works on your clone in your sandbox; it never comments, pushes or opens anything in the other team&#39;s fork on its own.</li><li><strong>Test it:</strong> tests that fail without your change, the team&#39;s whole suite passing, CI green on your PR.</li><li><strong>Open the PR</strong> with the <a href="./../templates/PULL_REQUEST_TEMPLATE.html">PR template</a>: a description you wrote yourself (what, why, how you verified it, risks), the AI disclosure section, the issue linked, and <code>Assisted-by: [tool and model]</code> trailers on AI-assisted commits.</li><li><strong>Submit the PR&#39;s URL</strong> on Canvas.</li></ol><h2 id="week-10-review-respond-decide" tabindex="-1">Week 10: review, respond, decide <a class="header-anchor" href="#week-10-review-respond-decide" aria-label="Permalink to &quot;Week 10: review, respond, decide&quot;">​</a></h2><p><strong>Closes before the week 11 Seminar (default 11:59 pm the night before).</strong></p><p><strong>As a receiving team:</strong></p><ol><li><strong>First review by the end of the week 10 Lab.</strong> The assigned reviewer reviews the PR with the <a href="./../templates/REVIEW.html">REVIEW template</a>: run it, read all of it, and leave located comments (file and line), marking which are blocking. Every claim you make about the PR is one you checked (observed), or is phrased as a question.</li><li><strong>A decision on every PR before the round closes:</strong> <strong>merge</strong> it (if it&#39;s correct, tested and fits your fork), <strong>request changes</strong> (saying exactly what would make it mergeable), or <strong>decline</strong> it (with your reasons, politely). The decision is your team&#39;s to make; nothing in anyone&#39;s grade depends on which one you choose, only on how well it&#39;s reasoned.</li><li><strong>Write your own review</strong> (🔴 AI off). An AI reviewer may run on the PR too, but your comments are yours. Comparing your review with the bot&#39;s afterwards is a good exercise, and week 9&#39;s lab is about exactly that comparison.</li></ol><p><strong>As an author:</strong></p><ol><li><strong>Answer every review comment</strong> within 48 hours of receiving it, and before the round closes: change the code or reply with a reason.</li><li><strong>Accept the decision.</strong> A declined PR, handled well, can still earn full author points.</li><li><strong>Submit the links</strong> to the reviews you gave and the PR you received responses on, on Canvas.</li></ol><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>Fixed clock.</strong> Grace tokens don&#39;t apply. A PR opened after the week 10 Seminar, or a review given after the round closes, loses the points for that part.</li><li><strong>Recognized absences</strong> (Regulations M-1 and M-3) get an equivalent task or new dates, for full credit. Tell the instructor as early as you can.</li><li><strong>Declared opt-out.</strong> If you can&#39;t take part for a serious reason that isn&#39;t a recognized absence, tell the instructor before the round opens. You then write a PR against <code>roomly</code> and review a seeded <code>roomly</code> PR instead, for up to 10 of the 20 points, as UT Austin scores a declared opt-out at half.</li><li><strong>No-shows</strong> score 0 for the part they missed.</li><li><strong>Review the code, never the person.</strong> No invented problems: flagging something that isn&#39;t there costs points, for people and for AI reviewers alike.</li><li><strong>Agents stay home.</strong> No agent posts in another team&#39;s fork. No unattended background agent works on another team&#39;s issues.</li><li><strong>After the round,</strong> your push permission on the other team&#39;s fork is removed. Merged PRs stay; open ones may be closed by the receiving team.</li></ul>',22)])])}const p=t(n,[["render",a]]);export{g as __pageData,p as default};
